content.solution:
function countByStatus(results) {
  const summary = { passed: 0, failed: 0 };
  for (const result of results) {
    if (result === "passed") {
      summary.passed++;
    } else if (result === "failed") {
      summary.failed++;
    }
  }
  return summary;
}

